    const c = seed(name + '-missing', source, { missingMain: true, noStaging: true });
    const started = Date.now();
    const r = await reader(c).done;
    assert.equal(r.code, 1, r.output);
    assert.ok(Date.now() - started < deadlineMs, 'genuinely missing dist must fail promptly');
    assert.match(r.output, /local bootstrap is not ready/);
    assert.match(r.output, /Recovery:/);
    assert.match(r.output, /packages[/\\]main[/\\]dist[/\\]cli-engine\.js/);
    assert.doesNotMatch(r.output, /CLI_SUCCESS/);
