// … and the SAME rule must reject each vacuous or inverted shape the intent names. Each injection
// changes exactly one thing, so a rule that had stopped looking at that thing is caught here.
for (const [defect, injected, expected] of [
  ['incomplete-trials', { ...matrix, finalRows: finalRows.slice(0, 2) }, 'final:incomplete-trials:2'],
  ['unreached-window', { ...matrix, finalRows: finalRows.map(row => ({ ...row, observation: '' })) }, 'final:unreached-promotion-window'],
  ['builder-failure', { ...matrix, finalRows: finalRows.map(row => ({ ...row, builderExit: 1 })) }, 'final:builder-failure'],
  ['control-failure', { ...matrix, controls: { ...matrix.controls, final: 2 } }, 'final:control-failed:2/3'],
  ['baseline-not-red', { ...matrix, baselineRows: baselineRows.map(row => ({ ...row, readerExit: 0 })) }, 'baseline:not-red:0/3'],
  ['mutant-not-red', { ...matrix, mutantRows: mutantRows.map(row => ({ ...row, readerExit: 0 })) }, 'mutant:not-red:0/3'],
  ['final-not-green', { ...matrix, finalRows: finalRows.map(row => ({ ...row, readerExit: 1 })) }, 'final:not-green:3/3'],
  ['off-target-assertion', { ...matrix, baselineRows: baselineRows.map(row => ({ ...row, targetAssertion: false })) }, 'baseline:reader-failure-not-target-assertion'],
]) {
  assert.ok(judgeMatrix(injected).includes(expected), `the acceptance rule must reject ${defect}`);
}
